            self._did_deactivation_event_cursors[tenant_id] = cursor
            events.append(
                {
                    "cursor": cursor,
                    "did": did,
                    "key_version": key_version,
                    "reason": reason,
                    "deactivated_at": deactivated_at,
                }
            )
            self._save_locked()
        except Exception:
            self._restore_locked(snapshot)
            raise
        return {
            "valid": True,
            "status_code": 201,
            "record": self._deactivation_notice_record(did, new_row),
        }

